<?php
/**
 * One Christian Church theme setup.
 *
 * @package One_Christian_Church
 */

defined( 'ABSPATH' ) || exit;

/**
 * Settings generated by build.py: page list, meta descriptions, default videos, font URL.
 *
 * @return array
 */
function occ_data() {
	static $data = null;
	if ( null === $data ) {
		$data = json_decode( file_get_contents( get_theme_file_path( 'inc/theme-data.json' ) ), true );
	}
	return $data;
}

add_action(
	'after_setup_theme',
	function () {
		add_theme_support( 'title-tag' );
		add_theme_support( 'custom-logo', array( 'flex-width' => true, 'flex-height' => true ) );
		add_theme_support( 'html5', array( 'script', 'style', 'navigation-widgets' ) );
	}
);

add_action(
	'wp_enqueue_scripts',
	function () {
		$version = occ_data()['version'];
		wp_enqueue_style( 'occ-fonts', occ_data()['fonts'], array(), null );
		wp_enqueue_style( 'occ-style', get_theme_file_uri( 'assets/css/style.css' ), array( 'occ-fonts' ), $version );
		wp_enqueue_script( 'occ-main', get_theme_file_uri( 'assets/js/main.js' ), array(), $version, array( 'strategy' => 'defer', 'in_footer' => true ) );
	}
);

add_action(
	'wp_head',
	function () {
		$key  = is_front_page() ? 'home' : ( is_page() ? get_post_field( 'post_name', get_queried_object_id() ) : '' );
		$desc = occ_data()['descriptions'][ $key ] ?? '';
		if ( $desc ) {
			printf( '<meta name="description" content="%s">' . "\n", esc_attr( $desc ) );
		}
		if ( ! has_site_icon() ) {
			printf( '<link rel="icon" href="%s" type="image/svg+xml">' . "\n", esc_url( get_theme_file_uri( 'assets/img/favicon.svg' ) ) );
		}
	}
);

/**
 * URL of one of the theme's pages, found by slug so it works with any permalink setting.
 *
 * @param string $slug   Page slug, or 'home'.
 * @param string $anchor Optional fragment without '#'.
 * @return string
 */
function occ_url( $slug, $anchor = '' ) {
	if ( 'home' === $slug ) {
		$url = home_url( '/' );
	} else {
		$page = get_page_by_path( $slug );
		$url  = $page ? get_permalink( $page ) : home_url( '/' . $slug . '/' );
	}
	return $anchor ? $url . '#' . $anchor : $url;
}

/**
 * Links for the header search, slug => URL. The search index (assets/search-index.json) names pages by slug.
 *
 * @return array
 */
function occ_search_pages() {
	$pages = array( 'home' => occ_url( 'home' ) );
	foreach ( occ_data()['pages'] as $page ) {
		$pages[ $page['slug'] ] = occ_url( $page['slug'] );
	}
	return $pages;
}

/**
 * Print the nav "current" class for a page slug.
 *
 * @param string $slug Page slug.
 */
function occ_current( $slug ) {
	if ( is_page( $slug ) || ( 'new' === $slug && is_page( 'new-here' ) ) ) {
		echo 'is-current';
	}
}

/**
 * Print the church logo: the Site Identity logo when one is set, otherwise the theme's vector copy of it.
 */
function occ_logo() {
	$id = get_theme_mod( 'custom_logo' );
	if ( $id ) {
		echo wp_get_attachment_image( $id, 'medium', false, array( 'class' => 'logo-img', 'alt' => '' ) );
		return;
	}
	echo file_get_contents( get_theme_file_path( 'assets/img/logo-mark.svg' ) ); // phpcs:ignore WordPress.Security.EscapeOutput -- theme's own SVG file.
}

/**
 * Print a muted, looping background video for a slot. main.js starts it when it scrolls into view.
 *
 * @param string $slot  Key from theme-data.json "videos".
 * @param bool   $eager True for hero videos that should start loading right away.
 */
function occ_video( $slot, $eager = false ) {
	$videos = occ_data()['videos'];
	if ( empty( $videos[ $slot ] ) ) {
		return;
	}
	// A Customizer URL wins; otherwise use assets/video/{slot}.mp4 if it was added to the theme.
	// With neither, print nothing and the animated colour background shows.
	$src = get_theme_mod( 'occ_video_' . $slot );
	if ( ! $src && file_exists( get_theme_file_path( 'assets/video/' . $slot . '.mp4' ) ) ) {
		$src = get_theme_file_uri( 'assets/video/' . $slot . '.mp4' );
	}
	if ( ! $src ) {
		return;
	}
	$attr = $eager ? 'src' : 'data-src';
	printf(
		'<video class="bg-video" data-slot="%s" muted loop playsinline preload="%s"%s aria-hidden="true">',
		esc_attr( $slot ),
		$eager ? 'auto' : 'metadata',
		$eager ? ' data-loaded="1"' : ''
	);
	printf( '<source %s="%s" type="video/mp4">', esc_attr( $attr ), esc_url( $src ) );
	echo '</video>';
}

/**
 * Customizer: swap each background video and hide the "design preview" note.
 */
add_action(
	'customize_register',
	function ( $wp_customize ) {
		$wp_customize->add_section(
			'occ_videos',
			array(
				'title'       => __( 'Background videos', 'one-christian-church' ),
				'description' => __( 'Upload each MP4 in Media > Add New, then paste its URL here. A slot left blank shows the animated colour background. Short, muted clips of 10 to 30 seconds at 720p work best.', 'one-christian-church' ),
				'priority'    => 30,
			)
		);
		foreach ( occ_data()['videos'] as $slot => $video ) {
			$wp_customize->add_setting( 'occ_video_' . $slot, array( 'sanitize_callback' => 'esc_url_raw' ) );
			$wp_customize->add_control(
				'occ_video_' . $slot,
				array(
					'label'   => $video['label'],
					'section' => 'occ_videos',
					'type'    => 'url',
				)
			);
		}
		$wp_customize->add_setting( 'occ_preview_badge', array( 'default' => true, 'sanitize_callback' => 'wp_validate_boolean' ) );
		$wp_customize->add_control(
			'occ_preview_badge',
			array(
				'label'   => __( 'Show the "Design preview" note', 'one-christian-church' ),
				'section' => 'occ_videos',
				'type'    => 'checkbox',
			)
		);
	}
);

/**
 * On activation, create any missing pages (each uses its matching page-{slug}.php template)
 * and make "Home" the static front page.
 */
add_action(
	'after_switch_theme',
	function () {
		$home = get_page_by_path( 'home' );
		$home_id = $home ? $home->ID : wp_insert_post(
			array(
				'post_type'   => 'page',
				'post_status' => 'publish',
				'post_title'  => 'Home',
				'post_name'   => 'home',
			)
		);
		foreach ( occ_data()['pages'] as $page ) {
			if ( ! get_page_by_path( $page['slug'] ) ) {
				wp_insert_post(
					array(
						'post_type'   => 'page',
						'post_status' => 'publish',
						'post_title'  => wp_specialchars_decode( $page['title'] ),
						'post_name'   => $page['slug'],
					)
				);
			}
		}
		if ( $home_id && ! is_wp_error( $home_id ) ) {
			update_option( 'show_on_front', 'page' );
			update_option( 'page_on_front', $home_id );
		}
	}
);
